<div class="space-y-6"><div><p class="text-sm font-bold uppercase tracking-wide text-yellow-700">{{ auth()->user()->role === 'parent' ? 'Parent / guardian account' : 'Student account' }}</p><h1 class="mt-1 text-2xl font-bold">Welcome, {{ auth()->user()->name }}</h1><p class="mt-1 text-slate-500">{{ $term ? $term->name.', '.$term->year : 'No current term has been opened.' }}</p></div>@if($students->isEmpty())<div class="rounded-2xl border border-amber-200 bg-amber-50 p-6 text-amber-900">No learner is linked to this account yet. Please contact the school registrar.</div>@else<div class="grid gap-5 lg:grid-cols-3"><section class="rounded-2xl border bg-white p-5 shadow-sm lg:col-span-2"><h2 class="font-bold">{{ auth()->user()->role === 'parent' ? 'My children' : 'My learner profile' }}</h2><div class="mt-4 grid gap-4 md:grid-cols-2">@foreach($students as $student)<article class="rounded-xl border border-slate-200 p-4"><h3 class="font-bold">{{ $student->name }}</h3><p class="text-sm text-slate-500">{{ $student->admission_no }} · {{ $student->schoolClass?->name }}{{ $student->stream ? ' · '.$student->stream->name : '' }}</p>@if(auth()->user()->role === 'parent')<div class="mt-4 grid grid-cols-3 gap-2 text-center text-xs"><div class="rounded-lg bg-slate-50 p-2"><b>{{ number_format($student->totalDue($term),0) }}</b><span class="block text-slate-500">Expected</span></div><div class="rounded-lg bg-emerald-50 p-2"><b>{{ number_format($student->totalPaid($term),0) }}</b><span class="block text-slate-500">Paid</span></div><div class="rounded-lg bg-rose-50 p-2"><b>{{ number_format(max(0,$student->balance($term)),0) }}</b><span class="block text-slate-500">Balance</span></div></div><div class="mt-3 text-xs text-slate-500">Recent payments: {{ $payments->get($student->id, collect())->take(2)->map(fn($payment)=>number_format($payment->amount,0).' on '.\Carbon\Carbon::parse($payment->paid_at)->format('d M'))->join(', ') ?: 'None recorded' }}</div>@endif<div class="mt-4 rounded-lg bg-slate-50 p-3 text-sm"><b>Attendance:</b> {{ $attendance->get($student->id, collect())->whereIn('status',['present','late'])->count() }} present/late, {{ $attendance->get($student->id, collect())->where('status','absent')->count() }} absent this term.</div><div class="mt-3 space-y-2">@forelse($exams->where('school_class_id',$student->school_class_id) as $exam)@php($blocked=$feeRule && $student->balance($exam->term)>0)<div class="flex items-center justify-between rounded-lg border p-3 text-sm"><span><b>{{ $exam->name }}</b><span class="block text-xs text-slate-500">{{ $exam->term->name }}, {{ $exam->term->year }}</span></span>@if($blocked)<span class="text-xs font-bold text-rose-600">Hidden pending fee clearance</span>@else<a target="_blank" href="{{ route('exams.report-card',[$exam,$student]) }}" class="font-bold text-yellow-700">View report</a>@endif</div>@empty<p class="text-sm text-slate-500">No published results for this learner.</p>@endforelse</div></article>@endforeach</div></section><aside class="rounded-2xl border bg-white p-5 shadow-sm"><h2 class="font-bold">Notifications</h2><div class="mt-3 space-y-3">@forelse($notifications->take(8) as $notification)<div class="rounded-lg bg-slate-50 p-3 text-sm"><span class="font-bold capitalize text-yellow-700">{{ $notification['type'] }}</span><p class="mt-1 text-slate-600">{{ $notification['message'] }}</p></div>@empty<p class="text-sm text-slate-500">You have no new notifications.</p>@endforelse</div></aside></div>@endif</div>
